import { forwardRef, useId } from 'react';
import type { InputHTMLAttributes } from 'react';
import './Input.css';

export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'id'> {
  /** Mono uppercase field label, rendered above the input. */
  label?: string;
  /** Small caption below the input — helper text or an inline error. */
  hint?: string;
}

/**
 * A labelled text field. Square corners, hairline border that turns solid
 * ink on focus — no colour, no glow.
 */
export const Input = forwardRef<HTMLInputElement, InputProps>(({ label, hint, className, ...rest }, ref) => {
  const generatedId = useId();
  const inputId = rest.name ?? generatedId;

  return (
    <div className="nv-field">
      {label && (
        <label className="nv-field__label" htmlFor={inputId}>
          {label}
        </label>
      )}
      <input ref={ref} id={inputId} className={['nv-input', className ?? ''].filter(Boolean).join(' ')} {...rest} />
      {hint && <span className="nv-field__hint">{hint}</span>}
    </div>
  );
});

Input.displayName = 'Input';
