import type { ReactNode } from 'react';
import './Table.css';

export interface TableColumn {
  /** Unique key, matched against each row's keys. */
  key: string;
  /** Header label. */
  label: ReactNode;
  /** Right-align the column — use for prices, quantities, anything numeric. */
  align?: 'left' | 'right';
}

export interface TableProps {
  columns: TableColumn[];
  /** Each row is a plain object keyed by column `key`; values can be any renderable node (e.g. a `PriceTag`). */
  rows: Array<Record<string, ReactNode>>;
  /** Alternates row background — helps scanning on wide/dense tables. */
  zebra?: boolean;
  className?: string;
}

/**
 * A data table for spec sheets and price grids — every numeric column sets
 * tabular figures automatically so prices and quantities line up.
 */
export function Table({ columns, rows, zebra = false, className }: TableProps) {
  const classes = ['nv-table', zebra ? 'nv-table--zebra' : '', className ?? ''].filter(Boolean).join(' ');

  return (
    <table className={classes}>
      <thead>
        <tr>
          {columns.map((col) => (
            <th key={col.key} data-align={col.align === 'right' ? 'right' : undefined}>
              {col.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, i) => (
          <tr key={i}>
            {columns.map((col) => (
              <td key={col.key} data-align={col.align === 'right' ? 'right' : undefined}>
                {row[col.key]}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
