import type { CSSProperties, HTMLAttributes, ReactNode } from 'react';
import './Section.css';

export type SectionTone = 'default' | 'soft' | 'inverse';

export interface SectionProps extends HTMLAttributes<HTMLElement> {
  /**
   * `default` (white), `soft` (light grey), `inverse` (ink — the brand's
   * "atelier" band). Alternate tones between stacked sections; that
   * alternation, not colour, is what carries the page's rhythm.
   */
  tone?: SectionTone;
  /** Max-width of the inner content column, e.g. `"880px"`. Defaults to 960px. */
  containerWidth?: string;
  children: ReactNode;
}

/**
 * A full-bleed page section with an inner reading column. This is the
 * primary layout building block — stack several with alternating `tone`.
 */
export function Section({ tone = 'default', containerWidth, style, className, children, ...rest }: SectionProps) {
  const classes = ['nv-section', tone !== 'default' ? `nv-section--${tone}` : '', className ?? ''].filter(Boolean).join(' ');
  const innerStyle = containerWidth ? ({ '--nv-container': containerWidth } as CSSProperties) : undefined;

  return (
    <section className={classes} style={style} {...rest}>
      <div className="nv-section__inner" style={innerStyle}>
        {children}
      </div>
    </section>
  );
}
