import type { HTMLAttributes, ReactNode } from 'react';
import './Card.css';

export interface CardProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Small mono label above the title — a reference code, a category. */
  eyebrow?: ReactNode;
  /** Card headline. Omit to build a fully custom body via `children` only. */
  title?: ReactNode;
  /** Lifts 2px with a soft shadow on hover — use for clickable/selectable cards, not static ones. */
  hoverable?: boolean;
  /** Pinned to the bottom of the card (price rows, a CTA) regardless of body length. */
  footer?: ReactNode;
  children?: ReactNode;
}

/**
 * The base surface for grouped content — product ranges, feature summaries,
 * pricing blocks. Square corners, hairline border, no drop shadow at rest.
 */
export function Card({ eyebrow, title, hoverable = false, footer, className, children, ...rest }: CardProps) {
  const classes = ['nv-card', hoverable ? 'nv-card--hover' : '', className ?? ''].filter(Boolean).join(' ');

  return (
    <div className={classes} {...rest}>
      {eyebrow && <div className="nv-card__eyebrow">{eyebrow}</div>}
      {title && <h3 className="nv-card__title">{title}</h3>}
      {children && <div className="nv-card__body">{children}</div>}
      {footer && <div className="nv-card__footer">{footer}</div>}
    </div>
  );
}
