import type { HTMLAttributes, ReactNode } from 'react';
import './Heading.css';

export type HeadingLevel = 1 | 2 | 3;
export type HeadingVoice = 'display' | 'ui';

export interface HeadingProps extends HTMLAttributes<HTMLHeadingElement> {
  /** Maps to `<h1>`/`<h2>`/`<h3>` and the matching type-scale step. */
  level?: HeadingLevel;
  /**
   * `display` (default) sets EB Garamond — the brand's editorial voice.
   * `ui` sets bold Inter — for structural/functional headings (a form
   * section, a table group) where the serif would read as too emotive.
   */
  voice?: HeadingVoice;
  /** Italicises the display face — reserve for one thesis line per page, not routine headings. */
  italic?: boolean;
  children: ReactNode;
}

export function Heading({ level = 2, voice = 'display', italic = false, className, children, ...rest }: HeadingProps) {
  const Tag = (`h${level}` as const) as 'h1' | 'h2' | 'h3';
  const classes = [
    'nv-heading',
    `nv-heading--${level}`,
    voice === 'ui' ? 'nv-heading--ui' : '',
    italic ? 'nv-heading--italic' : '',
    className ?? '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <Tag className={classes} {...rest}>
      {children}
    </Tag>
  );
}

export interface EyebrowProps extends HTMLAttributes<HTMLDivElement> {
  /** Optional leading marker — a section number (`"§03"`), a step count. */
  marker?: ReactNode;
  children: ReactNode;
}

/**
 * The small mono label that precedes a `Heading` — "§03 La gamme club".
 * Use the marker only when sections genuinely have a fixed reading order.
 */
export function Eyebrow({ marker, className, children, ...rest }: EyebrowProps) {
  return (
    <div className={['nv-eyebrow', className ?? ''].filter(Boolean).join(' ')} {...rest}>
      {marker && <span className="nv-eyebrow__marker">{marker}</span>}
      <span>{children}</span>
    </div>
  );
}
