import type { HTMLAttributes } from 'react';
import './PriceTag.css';

export interface PriceTagProps extends HTMLAttributes<HTMLSpanElement> {
  /** The number or range, pre-formatted — e.g. `"24–30"`, `"1 300"`. Kept as a string so ranges and dashes stay exact. */
  value: string;
  /** Currency mark. Defaults to `€`, placed after the value (French convention). */
  currency?: string;
  /** Small caption after the value — e.g. `"HT / pc"`, `"TTC"`. */
  unit?: string;
  /** Word before the value — e.g. `"à partir de"`. */
  prefix?: string;
  /** Compact size for use inside table cells or dense rows. */
  size?: 'md' | 'sm';
}

/**
 * A price, always set in tabular mono digits so columns of prices align.
 * Never used for arbitrary numbers — this is specifically a price mark.
 */
export function PriceTag({ value, currency = '€', unit, prefix, size = 'md', className, ...rest }: PriceTagProps) {
  const classes = ['nv-price', size === 'sm' ? 'nv-price--sm' : '', className ?? ''].filter(Boolean).join(' ');

  return (
    <span className={classes} {...rest}>
      {prefix && <span className="nv-price__prefix">{prefix}</span>}
      <span className="nv-price__value">
        {value}
        {currency && ` ${currency}`}
      </span>
      {unit && <span className="nv-price__unit">{unit}</span>}
    </span>
  );
}
