import type { HTMLAttributes, ReactNode } from 'react';
import './Badge.css';

export type BadgeVariant = 'outline' | 'solid';

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  /** `outline` (default) is a hairline rectangle; `solid` is ink-filled — use sparingly, it's the loudest mark in the system. */
  variant?: BadgeVariant;
  /** Place on an inverted (dark) `Section`. */
  inverse?: boolean;
  children: ReactNode;
}

/**
 * A small uppercase mono label — reference codes ("NR-100 → NR-111"), status
 * words, section markers. Always square corners, never a colour signal.
 */
export function Badge({ variant = 'outline', inverse = false, className, children, ...rest }: BadgeProps) {
  const classes = [
    'nv-badge',
    variant === 'solid' ? 'nv-badge--solid' : '',
    inverse ? 'nv-badge--inverse' : '',
    className ?? '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <span className={classes} {...rest}>
      {children}
    </span>
  );
}
