import { forwardRef } from 'react';
import type { AnchorHTMLAttributes, ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import './Button.css';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost';
export type ButtonSize = 'md' | 'sm';

interface SharedProps {
  /** Visual weight. `primary` is filled (ink), `secondary` is outlined, `ghost` is text-only. */
  variant?: ButtonVariant;
  /** Compact sizing for dense layouts (tables, cards). */
  size?: ButtonSize;
  /**
   * Place this button on an inverted (dark) `Section`. Flips the polarity so
   * a `primary` button stays legible — never combine with a light surface.
   */
  inverse?: boolean;
  children: ReactNode;
}

export type ButtonProps = SharedProps &
  ButtonHTMLAttributes<HTMLButtonElement> & {
    href?: undefined;
  };

export type ButtonLinkProps = SharedProps &
  AnchorHTMLAttributes<HTMLAnchorElement> & {
    href: string;
  };

/**
 * NovaRythm CTA. Renders a `<button>` by default, or an `<a>` when `href` is
 * passed (e.g. `mailto:`, an anchor jump, an external link).
 */
export const Button = forwardRef<HTMLButtonElement | HTMLAnchorElement, ButtonProps | ButtonLinkProps>(
  ({ variant = 'primary', size = 'md', inverse = false, className, children, ...rest }, ref) => {
    const classes = [
      'nv-button',
      `nv-button--${variant}`,
      size === 'sm' ? 'nv-button--sm' : '',
      inverse ? 'nv-button--inverse' : '',
      className ?? '',
    ]
      .filter(Boolean)
      .join(' ');

    if ('href' in rest && rest.href !== undefined) {
      const { href, ...anchorRest } = rest as AnchorHTMLAttributes<HTMLAnchorElement>;
      return (
        <a ref={ref as Ref<HTMLAnchorElement>} href={href} className={classes} {...anchorRest}>
          {children}
        </a>
      );
    }

    return (
      <button ref={ref as Ref<HTMLButtonElement>} className={classes} {...(rest as ButtonHTMLAttributes<HTMLButtonElement>)}>
        {children}
      </button>
    );
  },
);

Button.displayName = 'Button';
